            [ a owl:Restriction ; owl:onProperty :hasDateSegment ; owl:someValuesFrom :DTMSegment ]
            [ a owl:Restriction ; owl:onProperty :hasMonetaryAmountSegment ; owl:someValuesFrom :MOASegment ]
        )
    ] .

:OrganizationRoleAssignment a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            [ a owl:Restriction ; owl:onProperty :hasAgentRole ; owl:someValuesFrom :AgentRole ]
            [ a owl:Restriction ; owl:onProperty :hasOrganization ; owl:someValuesFrom :Organization ]
        )
    ] .

# Disjointness axioms
:BGMSegment owl:disjointWith :NADSegment, :DTMSegment, :MOASegment, :TAXSegment, :CUXSegment, :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:NADSegment owl:disjointWith :DTMSegment, :MOASegment, :TAXSegment, :CUXSegment, :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:DTMSegment owl:disjointWith :MOASegment, :TAXSegment, :CUXSegment, :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:MOASegment owl:disjointWith :TAXSegment, :CUXSegment, :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:TAXSegment owl:disjointWith :CUXSegment, :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:CUXSegment owl:disjointWith :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:RFFSegment owl:disjointWith :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:UNSSegment owl:disjointWith :LINSegment, :QTYSegment, :PRISegment .
:LINSegment owl:disjointWith :QTYSegment, :PRISegment .
:QTYSegment owl:disjointWith :PRISegment .

:Invoice owl:disjointWith :Organization .
:Item owl:disjointWith :Organization .
:Address owl:disjointWith :Organization .

# DisjointUnionOf
:Segment owl:disjointUnionOf (:BGMSegment :NADSegment :DTMSegment :MOASegment :TAXSegment :CUXSegment :RFFSegment :UNSSegment :LINSegment :QTYSegment :PRISegment) .
"}

{"owl_content": "@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#edifact-invoic-ontology> a owl:Ontology ;
    rdfs:label "EDIFACT D96A INVOIC Ontology" ;
    rdfs:comment "A deep, structured ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and validation mechanisms per EN 16931 and P2P-O." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope in an EDIFACT transmission, containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message instance within an interchange." .

:INVOICMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "INVOIC Message" ;
    rdfs:comment "An EDIFACT INVOIC message containing invoice data for global trade." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment, the building block of messages." .

:BGMSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NADSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment, specifying parties involved and their roles." .

:DTMSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment, e.g., invoice date, delivery date, tax point date." .

:MOASegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment, e.g., invoice amount, line amount." .

:TAXSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax segment, specifying tax type, rate, and amount." .

:CUXSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "CUX Segment" ;
    rdfs:comment "Currency segment, specifying currency for the invoice." .

:RFFSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "RFF Segment" ;
    rdfs:comment "Reference segment, specifying reference numbers and qualifiers." .

:UNSSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "UNS Segment" ;
    rdfs:comment "Section control segment, marking section boundaries in the message." .

:LINSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "LIN Segment" ;
    rdfs:comment "Line Item segment, specifying line item numbers and identifiers." .

:QTYSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment, specifying quantities for line items." .

:PRISegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PRI Segment" ;
    rdfs:comment "Price segment, specifying unit prices for line items." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment, grouping related simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A single, atomic data element within a composite or segment." .

:Invoice a owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "The business document representing a commercial invoice." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A legal entity involved in the invoice process." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "The role played by an organization in a transaction, e.g., Buyer, Supplier, Delivery Party." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address associated with an organization." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A single line in the invoice, representing an item sold." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service described in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "The net price of an item on the invoice." .

:TaxTotal a owl:Class ;
    rdfs:label "Tax Total" ;
    rdfs:comment "The total tax amount for the invoice." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total amount due on the invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice may be assigned." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier for organizations, addresses, or documents." .

:GLNIdentifier a owl:Class ;
    rdfs:subClassOf :Identifier ;
    rdfs:label "GLN Identifier" ;
    rdfs:comment "A Global Location Number used to identify parties in the supply chain." .

:EN16931Compliance a owl:Class ;
    rdfs:label "EN 16931 Compliance" ;
    rdfs:comment "Compliance with the European Standard EN 16931 for electronic invoicing." .

:P2POAlignment a owl:Class ;
    rdfs:label "Purchase-to-Pay Ontology Alignment" ;
    rdfs:comment "Alignment with the Purchase-to-Pay Ontology (P2P-O)." .

:SHACLConstraint a owl:Class ;
    rdfs:label "SHACL Constraint" ;
    rdfs:comment "A SHACL constraint used for validating invoice data." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "A pivot class for reifying the assignment of an agent role to an organization within an invoice context." .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an interchange envelope to a message." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a message to its constituent segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:label "has composite element" ;
    rdfs:comment "Relates a segment to its composite data elements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Relates a composite data element to its simple data elements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement .

:representsInvoice a owl:ObjectProperty ;
    rdfs:label "represents invoice" ;
    rdfs:comment "Relates an INVOIC message to the invoice it represents." ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :Invoice .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Relates an invoice to organizations involved in it." ;
    rdfs:domain :Invoice ;
    rdfs:range :Organization .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Relates an invoice to an organization role assignment." ;
    rdfs:domain :Invoice ;
    rdfs:range :OrganizationRoleAssignment .

:hasAgentRole a owl:ObjectProperty ;
    rdfs:label "has agent role" ;
    rdfs:comment "Relates an organization role assignment to an agent role." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole .

:hasOrganization a owl:ObjectProperty ;
    rdfs:label "has organization" ;
    rdfs:comment "Relates an organization role assignment to an organization." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization .

:hasAddress a owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Relates an organization to an address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "Relates an organization to its identifier(s)." ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier .

:hasBuyer a owl:ObjectProperty ;
    rdfs:label "has buyer" ;
    rdfs:comment "Relates an invoice to the buyer organization." ;
    rdfs:domain :Invoice ;
    rdfs:range :Organization .

:hasDeliveryParty a owl:ObjectProperty ;
    rdfs:label "has delivery party" ;
    rdfs:comment "Relates an invoice to the delivery party organization." ;
    rdfs:domain :Invoice ;
    rdfs:range :Organization .

:listsLineItem a owl:ObjectProperty ;
    rdfs:label "lists line item" ;
    rdfs:comment "Relates an invoice to its line items." ;
    rdfs:domain :Invoice ;
    rdfs:range :LineItem .

:lineItemOf a owl:ObjectProperty , owl:InverseFunctionalProperty ;
    rdfs:label "line item of" ;
    rdfs:comment "Inverse: Relates a line item to the invoice it belongs to." ;
    rdfs:domain :LineItem ;
    rdfs:range :Invoice .

:describesItem a owl:ObjectProperty ;
    rdfs:label "describes item" ;
    rdfs:comment "Relates a line item to the item it describes." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item .

:hasNetPrice a owl:ObjectProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Relates a line item to its net price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price .

:hasQuantity a owl:ObjectProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Relates a line item to its quantity." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal .

:hasTaxTotal a owl:ObjectProperty ;
    rdfs:label "has tax total" ;
    rdfs:comment "Relates an invoice to its total tax amount." ;
    rdfs:domain :Invoice ;
    rdfs:range :TaxTotal .

:hasInvoiceAmount a owl:ObjectProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Relates an invoice to its total amount." ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceAmount .

:assignedToBusinessProcess a owl:ObjectProperty ;
    rdfs:label "assigned to business process" ;
    rdfs:comment "Relates an invoice to a business process." ;
    rdfs:domain :Invoice ;
    rdfs:range :BusinessProcess .

:alignedToStandard a owl:ObjectProperty ;
    rdfs:label "aligned to standard" ;
    rdfs:comment "Relates an invoice to its EN 16931 compliance declaration." ;
    rdfs:domain :Invoice ;
    rdfs:range :EN16931Compliance .

:alignedToP2PO a owl:ObjectProperty ;
    rdfs:label "aligned to P2P-O" ;
    rdfs:comment "Relates an invoice to its P2P-O alignment declaration." ;
    rdfs:domain :Invoice ;
    rdfs:range :P2POAlignment .

:validatedBy a owl:ObjectProperty ;
    rdfs:label "validated by" ;
    rdfs:comment "Relates an invoice to a SHACL constraint for validation." ;
    rdfs:domain :Invoice ;
    rdfs:range :SHACLConstraint .

# Segment-level linking properties
:hasDateSegment a owl:ObjectProperty ;
    rdfs:label "has date segment" ;
    rdfs:comment "Links an invoice to its DTM segments (dates)." ;
    rdfs:domain :Invoice ;
    rdfs:range :DTMSegment .

:hasMonetaryAmountSegment a owl:ObjectProperty ;
    rdfs:label "has monetary amount segment" ;
    rdfs:comment "Links an invoice to its MOA segments (monetary amounts)." ;
    rdfs:domain :Invoice ;
    rdfs:range :MOASegment .

:hasTaxSegment a owl:ObjectProperty ;
    rdfs:label "has tax segment" ;
    rdfs:comment "Links an invoice to its TAX segments (taxes)." ;
    rdfs:domain :Invoice ;
    rdfs:range :TAXSegment .

:hasCurrencySegment a owl:ObjectProperty ;
    rdfs:label "has currency segment" ;
    rdfs:comment "Links an invoice to its CUX segments (currencies)." ;
    rdfs:domain :Invoice ;
    rdfs:range :CUXSegment .

:hasReferenceSegment a owl:ObjectProperty ;
    rdfs:label "has reference segment" ;
    rdfs:comment "Links an invoice to its RFF segments (references)." ;
    rdfs:domain :Invoice ;
    rdfs:range :RFFSegment .

:hasControlSegment a owl:ObjectProperty ;
    rdfs:label "has control segment" ;
    rdfs:comment "Links an invoice to its UNS segments (section control)." ;
    rdfs:domain :Invoice ;
    rdfs:range :UNSSegment .

:hasLineSegment a owl:ObjectProperty ;
    rdfs:label "has line segment" ;
    rdfs:comment "Links an invoice to its LIN segments (line items)." ;
    rdfs:domain :Invoice ;
    rdfs:range :LINSegment .

:hasQuantitySegment a owl:ObjectProperty ;
    rdfs:label "has quantity segment" ;
    rdfs:comment "Links an invoice to its QTY segments (quantities)." ;
    rdfs:domain :Invoice ;
    rdfs:range :QTYSegment .

:hasPriceSegment a owl:ObjectProperty ;
    rdfs:label "has price segment" ;
    rdfs:comment "Links an invoice to its PRI segments (prices)." ;
    rdfs:domain :Invoice ;
    rdfs:range :PRISegment .

#################################################################
# Data Properties
#################################################################

:hasInvoiceNumber a owl:DatatypeProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number." ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string .

:hasDate a owl:DatatypeProperty ;
    rdfs:label "has date" ;
    rdfs:comment "The date of the invoice." ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string .

:hasReferenceNumber a owl:DatatypeProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Reference number for the invoice or message." ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string .

:addressLine a owl:DatatypeProperty ;
    rdfs:label "address line" ;
    rdfs:comment "The street address or PO Box." ;
    rdfs:domain :Address ;
    rdfs:range xsd:string .

:city a owl:DatatypeProperty ;
    rdfs:label "city" ;
    rdfs:comment "The city of an address." ;
    rdfs:domain :Address ;
    rdfs:range xsd:string .

:postalCode a owl:DatatypeProperty ;
    rdfs:label "postal code" ;
    rdfs:comment "Postal code for the address." ;
    rdfs:domain :Address ;
    rdfs:range xsd:string .

:countryCode a owl:DatatypeProperty ;
    rdfs:label "country code" ;
    rdfs:comment "Country code for the address." ;
    rdfs:domain :Address ;
    rdfs:range xsd:string .

:identifierValue a owl:DatatypeProperty ;
    rdfs:label "identifier value" ;
    rdfs:comment "The value of an identifier (e.g., GLN, VAT)." ;
    rdfs:domain :Identifier ;
    rdfs:range xsd:string .

:itemName a owl:DatatypeProperty ;
    rdfs:label "item name" ;
    rdfs:comment "The name of an item." ;
    rdfs:domain :Item ;
    rdfs:range xsd:string .

:itemDescription a owl:DatatypeProperty ;
    rdfs:label "item description" ;
    rdfs:comment "The description of an item." ;
    rdfs:domain :Item ;
    rdfs:range xsd:string .

:priceValue a owl:DatatypeProperty ;
    rdfs:label "price value" ;
    rdfs:comment "The value of a price." ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal .

:taxValue a owl:DatatypeProperty ;
    rdfs:label "tax value" ;
    rdfs:comment "The value of the total tax." ;
    rdfs:domain :TaxTotal ;
    rdfs:range xsd:decimal .

:invoiceAmountValue a owl:DatatypeProperty ;
    rdfs:label "invoice amount value" ;
    rdfs:comment "The value of the total invoice amount." ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range xsd:decimal .

:dtmQualifier a owl:DatatypeProperty ;
    rdfs:label "DTM qualifier" ;
    rdfs:comment "Qualifier for the DTM segment (e.g., 137=Invoice date)." ;
    rdfs:domain :DTMSegment ;
    rdfs:range xsd:string .

:dtmValue a owl:DatatypeProperty ;
    rdfs:label "DTM value" ;
    rdfs:comment "The value for the date/time/period." ;
    rdfs:domain :DTMSegment ;
    rdfs:range xsd:string .

:moaQualifier a owl:DatatypeProperty ;
    rdfs:label "MOA qualifier" ;
    rdfs:comment "Qualifier for the MOA segment (e.g., 79=Invoice amount)." ;
    rdfs:domain :MOASegment ;
    rdfs:range xsd:string .

:moaValue a owl:DatatypeProperty ;
    rdfs:label "MOA value" ;
    rdfs:comment "Monetary amount value in MOA segment." ;
    rdfs:domain :MOASegment ;
    rdfs:range xsd:decimal .

:taxQualifier a owl:DatatypeProperty ;
    rdfs:label "TAX qualifier" ;
    rdfs:comment "Qualifier for the TAX segment." ;
    rdfs:domain :TAXSegment ;
    rdfs:range xsd:string .

:taxType a owl:DatatypeProperty ;
    rdfs:label "tax type" ;
    rdfs:comment "Type of tax (e.g., VAT)." ;
    rdfs:domain :TAXSegment ;
    rdfs:range xsd:string .

:taxRate a owl:DatatypeProperty ;
    rdfs:label "tax rate" ;
    rdfs:comment "Tax rate percentage." ;
    rdfs:domain :TAXSegment ;
    rdfs:range xsd:decimal .

:currencyQualifier a owl:DatatypeProperty ;
    rdfs:label "currency qualifier" ;
    rdfs:comment "Qualifier for the CUX segment." ;
    rdfs:domain :CUXSegment ;
    rdfs:range xsd:string .

:currencyCode a owl:DatatypeProperty ;
    rdfs:label "currency code" ;
    rdfs:comment "Currency code (e.g., EUR, USD)." ;
    rdfs:domain :CUXSegment ;
    rdfs:range xsd:string .

:referenceQualifier a owl:DatatypeProperty ;
    rdfs:label "reference qualifier" ;
    rdfs:comment "Qualifier for the RFF segment." ;
    rdfs:domain :RFFSegment ;
    rdfs:range xsd:string .

:referenceValue a owl:DatatypeProperty ;
    rdfs:label "reference value" ;
    rdfs:comment "Reference value for the RFF segment." ;
    rdfs:domain :RFFSegment ;
    rdfs:range xsd:string .

:unsQualifier a owl:DatatypeProperty ;
    rdfs:label "UNS qualifier" ;
    rdfs:comment "Qualifier for the UNS segment." ;
    rdfs:domain :UNSSegment ;
    rdfs:range xsd:string .

:lineNumber a owl:DatatypeProperty ;
    rdfs:label "line number" ;
    rdfs:comment "Line item number in LIN segment." ;
    rdfs:domain :LINSegment ;
    rdfs:range xsd:string .

:itemIdentifier a owl:DatatypeProperty ;
    rdfs:label "item identifier" ;
    rdfs:comment "Item identifier in LIN segment." ;
    rdfs:domain :LINSegment ;
    rdfs:range xsd:string .

:qtyQualifier a owl:DatatypeProperty ;
    rdfs:label "quantity qualifier" ;
    rdfs:comment "Qualifier for the QTY segment." ;
    rdfs:domain :QTYSegment ;
    rdfs:range xsd:string .

:qtyValue a owl:DatatypeProperty ;
    rdfs:label "quantity value" ;
    rdfs:comment "Quantity value in QTY segment." ;
    rdfs:domain :QTYSegment ;
    rdfs:range xsd:decimal .

:priceQualifier a owl:DatatypeProperty ;
    rdfs:label "price qualifier" ;
    rdfs:comment "Qualifier for the PRI segment." ;
    rdfs:domain :PRISegment ;
    rdfs:range xsd:string .

:priceAmount a owl:DatatypeProperty ;
    rdfs:label "price amount" ;
    rdfs:comment "Price amount in PRI segment." ;
    rdfs:domain :PRISegment ;
    rdfs:range xsd:decimal .

#################################################################
# Restrictions & Axioms (Examples)
#################################################################

:Invoice a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            [ a owl:Restriction ; owl:onProperty :hasInvoiceNumber ; owl:someValuesFrom xsd:string ]
            [ a owl:Restriction ; owl:onProperty :listsLineItem ; owl:someValuesFrom :LineItem ]
            [ a owl:Restriction ; owl:onProperty :hasBuyer ; owl:someValuesFrom :Organization ]
            [ a owl:Restriction ; owl:onProperty :hasDateSegment ; owl:someValuesFrom :DTMSegment ]
            [ a owl:Restriction ; owl:onProperty :hasMonetaryAmountSegment ; owl:someValuesFrom :MOASegment ]
        )
    ] .

:OrganizationRoleAssignment a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            [ a owl:Restriction ; owl:onProperty :hasAgentRole ; owl:someValuesFrom :AgentRole ]
            [ a owl:Restriction ; owl:onProperty :hasOrganization ; owl:someValuesFrom :Organization ]
        )
    ] .

# Disjointness axioms
:BGMSegment owl:disjointWith :NADSegment, :DTMSegment, :MOASegment, :TAXSegment, :CUXSegment, :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:NADSegment owl:disjointWith :DTMSegment, :MOASegment, :TAXSegment, :CUXSegment, :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:DTMSegment owl:disjointWith :MOASegment, :TAXSegment, :CUXSegment, :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:MOASegment owl:disjointWith :TAXSegment, :CUXSegment, :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:TAXSegment owl:disjointWith :CUXSegment, :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:CUXSegment owl:disjointWith :RFFSegment, :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:RFFSegment owl:disjointWith :UNSSegment, :LINSegment, :QTYSegment, :PRISegment .
:UNSSegment owl:disjointWith :LINSegment, :QTYSegment, :PRISegment .
:LINSegment owl:disjointWith :QTYSegment, :PRISegment .
:QTYSegment owl:disjointWith :PRISegment .

:Invoice owl:disjointWith :Organization .
:Item owl:disjointWith :Organization .
:Address owl:disjointWith :Organization .

# DisjointUnionOf
:Segment owl:disjointUnionOf (:BGMSegment :NADSegment :DTMSegment :MOASegment :TAXSegment :CUXSegment :RFFSegment :UNSSegment :LINSegment :QTYSegment :PRISegment) .
"}

