:assignedToBusinessProcess a owl:ObjectProperty ;
    rdfs:label "assigned to business process" ;
    rdfs:comment "Relates an invoice to a business process." ;
    rdfs:domain :Invoice ;
    rdfs:range :BusinessProcess ;
    owl:inverseOf :isBusinessProcessOfInvoice .

:isBusinessProcessOfInvoice a owl:ObjectProperty ;
    rdfs:label "is business process of invoice" ;
    rdfs:comment "Inverse of assignedToBusinessProcess: Relates a business process to its invoice." ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :Invoice ;
    owl:inverseOf :assignedToBusinessProcess .

:alignedToStandard a owl:ObjectProperty ;
    rdfs:label "aligned to standard" ;
    rdfs:comment "Relates an invoice to its EN 16931 compliance declaration." ;
    rdfs:domain :Invoice ;
    rdfs:range :EN16931Compliance ;
    owl:inverseOf :isStandardAlignmentOfInvoice .

:isStandardAlignmentOfInvoice a owl:ObjectProperty ;
    rdfs:label "is standard alignment of invoice" ;
    rdfs:comment "Inverse of alignedToStandard: Relates an EN16931Compliance to its invoice." ;
    rdfs:domain :EN16931Compliance ;
    rdfs:range :Invoice ;
    owl:inverseOf :alignedToStandard .

:alignedToP2PO a owl:ObjectProperty ;
    rdfs:label "aligned to P2P-O" ;
    rdfs:comment "Relates an invoice to its P2P-O alignment declaration." ;
    rdfs:domain :Invoice ;
    rdfs:range :P2POAlignment ;
    owl:inverseOf :isP2POAlignmentOfInvoice .

:isP2POAlignmentOfInvoice a owl:ObjectProperty ;
    rdfs:label "is P2P-O alignment of invoice" ;
    rdfs:comment "Inverse of alignedToP2PO: Relates a P2POAlignment to its invoice." ;
    rdfs:domain :P2POAlignment ;
    rdfs:range :Invoice ;
    owl:inverseOf :alignedToP2PO .

:validatedBy a owl:ObjectProperty ;
    rdfs:label "validated by" ;
    rdfs:comment "Relates an invoice to a SHACL constraint for validation." ;
    rdfs:domain :Invoice ;
    rdfs:range :SHACLConstraint ;
    owl:inverseOf :validatesInvoice .

:validatesInvoice a owl:ObjectProperty ;
    rdfs:label "validates invoice" ;
    rdfs:comment "Inverse of validatedBy: Relates a SHACL constraint to the invoice it validates." ;
    rdfs:domain :SHACLConstraint ;
    rdfs:range :Invoice ;
    owl:inverseOf :validatedBy .

# Segment-level linking properties
:hasDateSegment a owl:ObjectProperty ;
    rdfs:label "has date segment" ;
    rdfs:comment "Links an invoice to its DTM segments (dates)." ;
    rdfs:domain :Invoice ;
    rdfs:range :DTMSegment ;
    owl:inverseOf :isDateSegmentOfInvoice .

:isDateSegmentOfInvoice a owl:ObjectProperty ;
    rdfs:label "is date segment of invoice" ;
    rdfs:comment "Inverse of hasDateSegment: Relates a DTM segment to its invoice." ;
    rdfs:domain :DTMSegment ;
    rdfs:range :Invoice ;
    owl:inverseOf :hasDateSegment .

:hasMonetaryAmountSegment a owl:ObjectProperty ;
    rdfs:label "has monetary amount segment" ;
    rdfs:comment "Links an invoice to its MOA segments (monetary amounts)." ;
